/** Local TDS1 authentication and decryption using caller-supplied keys. No network access. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    isEncryptedSave, decryptSave
 * depends    src/save-decoder/types
 * used by    src/node/decode-save, src/save-decoder/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { z } from 'zod'
import type { SaveDecodeOptions } from './types'

const MAX_SAVE_BYTES = 8 * 1024 * 1024
const keySchema = z.union([z.instanceof(Uint8Array), z.string()])
const keysSchema = z.object({ encryption: keySchema, authentication: keySchema, mask: keySchema }).strict()

export function isEncryptedSave(bytes: Uint8Array): boolean {
  return bytes.length >= 4 && bytes[0] === 0x54 && bytes[1] === 0x44 && bytes[2] === 0x53 && bytes[3] === 0x31
}

function keyBytes(value: Uint8Array | string): Uint8Array<ArrayBuffer> {
  if (value instanceof Uint8Array) {
    if (value.length !== 32) throw new Error('Each save decryption key must contain 32 bytes.')
    return Uint8Array.from(value)
  }
  if (!/^[A-Za-z0-9+/]{43}=$/.test(value)) throw new Error('Save keys must be 32 bytes or canonical base64.')
  const binary = atob(value)
  if (binary.length !== 32 || btoa(binary) !== value) throw new Error('Invalid save key encoding.')
  return Uint8Array.from(binary, c => c.charCodeAt(0))
}

function unmask(bytes: Uint8Array, key: Uint8Array): Uint8Array {
  let state = 2166136261
  for (const value of key) state = Math.imul(state ^ value, 16777619) >>> 0
  for (let i = 0; i < bytes.length; i++) {
    state = (Math.imul(state, 1664525) + key[i & 31] + 1013904223) >>> 0
    const mask = (key[(i * 5 + 3) & 31] ^ (state >>> 24) ^ (state >>> 9)) & 255
    const shift = (state >>> 6) & 7
    const rotated = ((bytes[i] >>> shift) | (bytes[i] << (8 - shift))) & 255
    bytes[i] = ((rotated - (state >>> 13)) & 255) ^ mask
  }
  return bytes
}

/** Return decrypted compressed bytes locally; unencrypted input needs no key. */
export async function decryptSave(input: Uint8Array, options?: SaveDecodeOptions): Promise<Uint8Array> {
  if (!isEncryptedSave(input)) return input
  if (input.length > MAX_SAVE_BYTES) throw new Error('Encrypted save exceeds the 8 MiB size limit.')
  if (input.length < 69 || (input.length - 53) % 16) throw new Error('Encrypted save is incomplete or corrupt.')
  if (input[4] !== 1) throw new Error('Unsupported encrypted save version.')
  if (!options?.keys) throw new Error('Encrypted saves require caller-supplied decryption keys in options.keys.')
  const parsed = keysSchema.safeParse(options.keys)
  if (!parsed.success) throw new Error('Supply encryption, authentication and mask keys for this save.')
  // Snapshot both the save and caller-owned keys before the first asynchronous operation.
  const bytes = Uint8Array.from(input)
  const keys = {
    encryption: keyBytes(parsed.data.encryption),
    authentication: keyBytes(parsed.data.authentication),
    mask: keyBytes(parsed.data.mask),
  }
  const subtle = globalThis.crypto?.subtle
  if (!subtle) throw new Error('Local save decryption requires Web Crypto (HTTPS or localhost in a browser, or Node 20+).')
  const auth = await subtle.importKey('raw', keys.authentication, { name: 'HMAC', hash: 'SHA-256' }, false, ['verify'])
  const authenticated = new Uint8Array(bytes.length - 36)
  authenticated.set(bytes.subarray(4, 21))
  authenticated.set(bytes.subarray(53), 17)
  if (!await subtle.verify('HMAC', auth, bytes.subarray(21, 53), authenticated)) {
    throw new Error('Save integrity check failed: incorrect keys or damaged save.')
  }
  const aes = await subtle.importKey('raw', keys.encryption, 'AES-CBC', false, ['decrypt'])
  let plaintext: ArrayBuffer
  try { plaintext = await subtle.decrypt({ name: 'AES-CBC', iv: bytes.subarray(5, 21) }, aes, bytes.subarray(53)) }
  catch { throw new Error('Save decryption failed: incorrect keys or damaged save.') }
  return unmask(new Uint8Array(plaintext), keys.mask)
}
